export const getReportsVerifyUrl = (snapshotId: string,
    params: ReportsVerifyParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/public/verify/${snapshotId}?${stringifiedParams}` : `/api/public/verify/${snapshotId}`
}

